/** Copies only finite failure evidence; no signaling, exception text or extra fields are retained. */
export declare function retainedRenewalFailure(evidence: RenewalEvidence, sequence: number): RetainedRenewalFailure;
/** Maps known errors to fixed categories; arbitrary details are never retained. */
export declare function renewalFailure(error: unknown): RenewalFailure;
